#requires -RunAsAdministrator
#requires -Version 5.1
[CmdletBinding()]param([int]$WarnDays=60)
$root='C:\ProgramData\BlueRidge\SecurityReports';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$out=Join-Path $root "certificate-expiration-$env:COMPUTERNAME-$s.csv";Start-Transcript -Path (Join-Path $logs 'certificate-expiration-report.log') -Append|Out-Null
try{$stores=@('Cert:\LocalMachine\My','Cert:\LocalMachine\WebHosting','Cert:\CurrentUser\My');$rows=foreach($store in $stores){if(Test-Path $store){Get-ChildItem $store -ErrorAction SilentlyContinue|ForEach-Object{$days=[math]::Floor(($_.NotAfter-(Get-Date)).TotalDays);[pscustomobject]@{Store=$store;Subject=$_.Subject;Issuer=$_.Issuer;Thumbprint=$_.Thumbprint;DnsNames=($_.DnsNameList.Unicode -join ';');NotBefore=$_.NotBefore;NotAfter=$_.NotAfter;DaysRemaining=$days;HasPrivateKey=$_.HasPrivateKey;EnhancedKeyUsage=($_.EnhancedKeyUsageList.FriendlyName -join ';');Status=if($days -lt 0){'Expired'}elseif($days -le $WarnDays){'ExpiringSoon'}else{'OK'}}}}};$rows|Sort DaysRemaining|Export-Csv $out -NoTypeInformation -Encoding UTF8;$rows|Where Status -ne 'OK'|Format-Table Subject,NotAfter,DaysRemaining,Status -AutoSize;Write-Host "Certificate report: $out" -ForegroundColor Green}finally{Stop-Transcript|Out-Null}
